#!/usr/bin/env bash
# Apply WAF rule file generated by Defense Matrix.
# Usage: bash actions/waf_rule.sh /path/to/waf-rules-....json
set -euo pipefail
FILE="${1:-}"
if [[ -z "$FILE" || ! -f "$FILE" ]]; then
  echo "usage: waf_rule.sh <rules.json>"
  exit 2
fi
echo "WAF: loaded rules from $FILE"
# Hook point: Cloudflare / Vercel Firewall / nginx — founder wires real push here.
COUNT=$(grep -c '"id"' "$FILE" || true)
echo "WAF: $COUNT rule ids staged"
exit 0
